            bool fence = false;
            for (int c = 0; c < W * H; c++)
            {
                if (cellZone[c] == GenData.Z_NONE || cellRoom[c] != r) continue;
                if (first < 0) first = c;
                cells++;
                for (int d = 0; d < 4; d++) if (EdgeType(c % W, c / W, d) == GenData.E_FENCE) fence = true;
            }
